text:
{
  "jobs": [
    {
      "text": "Регулярно созваниваться с матерью, чаще всего по дороге с работы, и с отцом по выходным",
      "quote": "Чаще всего звоню маме, обычно по дороге с работы. Иногда на пять минут, а иногда я уже машину припарковал и ещё полчаса сижу слушаю. С папой чаще созваниваемся по выходным."
    },
    {
      "text": "Помогать родителям разбираться с подозрительными звонками и проверять, не произошло ли чего",
      "quote": "Я спросил, успела ли она что-нибудь сообщить, и предложил позвонить в банк по номеру на карте."
    },
    {
      "text": "Быть на связи с родителями, чтобы они могли обратиться в любой момент, даже во время работы",
      "quote": "Я ей сказал, что в таком случае можно звонить хоть посреди совещания."
    },
    {
      "text": "Получать уведомление, когда сервис остановил подозрительный звонок, и понимать, успел ли родитель поговорить",
      "quote": "Я бы хотел сразу видеть, успела мама поговорить или у неё телефон даже не зазвонил. От этого зависит, брошу ли я всё, чтобы ей перезвонить."
    }
  ],
  "pains": [
    {
      "text": "Тревога из-за обычного звонка без пометки, на который родитель может ответить",
      "quote": "Больше всего меня тревожит обычный звонок без всякой пометки."
    },
    {
      "text": "Родитель полагается на определитель номера и не ждёт подвоха, если телефон не предупредил",
      "quote": "Ну телефон же меня не предупредил"
    },
    {
      "text": "Родитель боится отвлекать на работе и не звонит сразу",
      "quote": "Мама тогда призналась, что боялась отвлечь меня на работе."
    },
    {
      "text": "Непонятно, что увидит сам родитель при срабатывании защиты — может решить, что пропала связь, и перезвонить мошеннику",
      "quote": "Если разговор просто оборвётся, она ведь может решить, что пропала связь, и набрать тот же номер."
    },
    {
      "text": "После истории с поликлиникой беспокоит, что нужный номер нельзя будет быстро разблокировать",
      "quote": "А меня после истории с поликлиникой остановило бы, если нужный номер нельзя было бы быстро разблокировать."
    }
  ],
  "current_solutions": [
    {
      "text": "Определитель номера у обоих родителей; при пометке «спам» трубку не берут",
      "quote": "У обоих родителей стоит определитель номера. Если на экране пометка «спам», они обычно трубку не берут."
    },
    {
      "text": "Пробовали заглушить все незнакомые номера, но отключили из-за звонка из поликлиники",
      "quote": "Пробовали у мамы заглушить все незнакомые номера, но как раз в ту неделю ей из поликлиники звонили перенести приём. После этого выключили."
    },
    {
      "text": "Проверка через банк по номеру на карте",
      "quote": "предложил позвонить в банк по номеру на карте"
    },
    {
      "text": "Платный определитель на своём телефоне примерно за сто рублей в месяц",
      "quote": "За определитель на своём телефоне я плачу около ста рублей в месяц."
    }
  ],
  "barriers": [
    {
      "text": "Барьер выбора: если платить за каждый номер отдельно, сначала хочется попробовать",
      "quote": "Если по 150 за каждый номер, уже захотел бы сначала попробовать."
    },
    {
      "text": "Барьер понимания: непонятно, что увидит сам родитель при срабатывании защиты",
      "quote": "Ещё непонятно, что увидит сама мама."
    },
    {
      "text": "Барьер выбора: важно, чтобы родитель сам решал, подключать услугу или нет",
      "quote": "И ей важно самой решать, подключать услугу или нет."
    },
    {
      "text": "Барьер выбора: нужна возможность быстро разблокировать нужный номер",
      "quote": "А меня после истории с поликлиникой остановило бы, если нужный номер нельзя было бы быстро разблокировать."
    }
  ],
  "triggers": [
    {
      "text": "Звонок мошенников матери среди рабочего дня с упоминанием кредита на её имя",
      "quote": "Пару недель назад мама сама позвонила мне среди рабочего дня. Сказала, что ей только что звонили «из банка» по поводу кредита на её имя."
    },
    {
      "text": "Сомнение матери, не появился ли кредит на самом деле",
      "quote": "[имя], а вдруг кредит и правда есть?"
    },
    {
      "text": "Осознание, что после привычки к определителю начинаешь на него полагаться",
      "quote": "Сам бы после пары месяцев с определителем начал на него полагаться."
    }
  ],
  "words": [
    "«из банка»",
    "«спам»",
    "«Ну телефон же меня не предупредил»",
    "«а вдруг кредит и правда есть?»",
    "«брошу ли я всё»",
    "«сработала защита»",
    "«быстро разблокировать»",
    "«без долгих раздумий»",
    "«на пробу»"
  ],
  "surprises": [
    {
      "text": "Мать сама позвонила сыну среди рабочего дня, хотя обычно боится отвлекать",
      "quote": "Пару недель назад мама сама позвонила мне среди рабочего дня."
    },
    {
      "text": "Отключение защиты от незнакомых номеров из-за одного нужного звонка из поликлиники",
      "quote": "Пробовали у мамы заглушить все незнакомые номера, но как раз в ту неделю ей из поликлиники звонили перенести приём. После этого выключили."
    },
    {
      "text": "Готовность платить за защиту для обоих родителей без раздумий, но при условии одной цены за двоих",
      "quote": "За такую защиту для обоих родителей рублей 150 в месяц я бы платил без долгих раздумий. Если по 150 за каждый номер, уже захотел бы сначала попробовать."
    }
  ]
}
